import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0) && caller != address(this));
        vm.prank(caller);
        // Set value to be <= totalRemaining so that toGive > 0 
        // We can set value by manipulating totalRemaining? Not directly, but we ensure totalRemaining is sufficient.
